import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const b=JSON.parse('{"title":"Wedding Invitation","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/03-wedding-invitation.md","filePath":"en/more/maltese/practice/emails/03-wedding-invitation.md"}'),r={name:"en/more/maltese/practice/emails/03-wedding-invitation.md"},n=d('<h1 id="wedding-invitation" tabindex="-1">Wedding Invitation <a class="header-anchor" href="#wedding-invitation" aria-label="Permalink to &quot;Wedding Invitation&quot;">​</a></h1><p><strong>Scenario:</strong> A couple invites friends and family to their wedding ceremony and reception.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a><strong>Mingħand (From):</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data (Date):</strong> 20 ta&#39; Ġunju 2026 <strong>Suġġett (Subject):</strong> Stedina għat-tieġ</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 20 ta&#39; Ġunju 2026 <strong>Suġġett:</strong> Stedina għat-tieġ</p><p>Għeżież ħbieb,</p><p>Għandna pjaċir nistednukom għat-tieġ tagħna.</p><p>Iċ-ċerimonja se ssir nhar is-Sibt, 18 ta&#39; Lulju.</p><p>Tibda fil-ħamsa ta&#39; wara nofsinhar fil-knisja ta&#39; San Pawl.</p><p>Wara ċ-ċerimonja, se jkun hemm riċeviment fil-lukanda Marina.</p><p>Jekk jogħġobkom, ikkonfermaw jekk tistgħux tattendu sal-1 ta&#39; Lulju.</p><p>Nistennew bil-ħerqa li niċċelebraw dan il-jum speċjali magħkom.</p><p>Tislijiet, Anna u Mark</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a></td><td>email address</td><td>Recipients&#39; (friends and family) email</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>Translation:</strong> From: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>email address</td><td>Sender&#39;s (Anna&#39;s) email</td></tr></tbody></table><p><strong>Malti:</strong> Data: 20 ta&#39; Ġunju 2026</p><p><strong>Translation:</strong> Date: 20 June 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>20</td><td>twenty</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ġunju</td><td>June</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Stedina għat-tieġ</p><p><strong>Translation:</strong> Subject: Wedding Invitation</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Stedina</td><td>invitation</td><td>Feminine noun</td></tr><tr><td>għat-tieġ</td><td>to the wedding</td><td>Contracted <code>għal</code> + <code>it-tieġ</code></td></tr></tbody></table><p><strong>Malti:</strong> Għeżież ħbieb,</p><p><strong>Translation:</strong> Dear friends,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għeżież</td><td>dear</td><td>Masculine plural form used to address a group</td></tr><tr><td>ħbieb</td><td>friends</td><td>Plural of <code>ħabib</code></td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Għandna pjaċir nistednukom għat-tieġ tagħna.</p><p><strong>Translation:</strong> We are pleased to invite you to our wedding.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandna</td><td>we have</td><td>First-person plural form of <code>għand</code></td></tr><tr><td>pjaċir</td><td>pleasure; delight</td><td><code>għandna pjaċir</code> means &quot;we are pleased&quot;</td></tr><tr><td>nistednukom</td><td>we invite you (plural)</td><td><code>nistiednu</code> &quot;we invite&quot; + <code>-kom</code> &quot;you (plural)&quot;</td></tr><tr><td>għat-tieġ</td><td>to the wedding</td><td>Contracted <code>għal</code> + <code>it-tieġ</code></td></tr><tr><td>tagħna</td><td>our; ours</td><td>First-person plural possessive</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Iċ-ċerimonja se ssir nhar is-Sibt, 18 ta&#39; Lulju.</p><p><strong>Translation:</strong> The ceremony will take place on Saturday, 18 July.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Iċ-ċerimonja</td><td>the ceremony</td><td>Feminine noun with the definite article</td></tr><tr><td>se</td><td>will</td><td>Future marker</td></tr><tr><td>ssir</td><td>take place; happen</td><td>Feminine form of <code>isir</code>, agreeing with <code>ċerimonja</code></td></tr><tr><td>nhar</td><td>on the day of</td><td>Introduces a weekday/date</td></tr><tr><td>is-Sibt</td><td>Saturday</td><td>Weekday with the definite article</td></tr><tr><td>18</td><td>eighteen</td><td>Day of the month</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and month in a date</td></tr><tr><td>Lulju</td><td>July</td><td>Month name</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Tibda fil-ħamsa ta&#39; wara nofsinhar fil-knisja ta&#39; San Pawl.</p><p><strong>Translation:</strong> It starts at five in the afternoon at St Paul&#39;s Church.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tibda</td><td>it starts</td><td>Third-person feminine singular, referring to the ceremony</td></tr><tr><td>fil-ħamsa</td><td>at five</td><td>Contracted <code>f&#39;</code> &quot;at&quot; + clock-hour form</td></tr><tr><td>ta&#39;</td><td>of; during</td><td>Links the time and part of day</td></tr><tr><td>wara</td><td>after</td><td>Combines with <code>nofsinhar</code> to mean &quot;afternoon&quot;</td></tr><tr><td>nofsinhar</td><td>midday</td><td><code>wara nofsinhar</code> means &quot;afternoon&quot;</td></tr><tr><td>fil-knisja</td><td>at the church</td><td>Contracted <code>f&#39;</code> + <code>il-knisja</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the church and its name</td></tr><tr><td>San</td><td>Saint</td><td>Title before a name</td></tr><tr><td>Pawl</td><td>Paul</td><td>Name</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Wara ċ-ċerimonja, se jkun hemm riċeviment fil-lukanda Marina.</p><p><strong>Translation:</strong> After the ceremony, there will be a reception at the Marina Hotel.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Wara</td><td>after</td><td>Preposition of time</td></tr><tr><td>ċ-ċerimonja</td><td>the ceremony</td><td>Refers to <code>iċ-ċerimonja</code> in this context</td></tr><tr><td>se</td><td>will</td><td>Future marker</td></tr><tr><td>jkun</td><td>be; there will be</td><td>Form of <code>ikun</code></td></tr><tr><td>hemm</td><td>there; there is</td><td><code>se jkun hemm</code> means &quot;there will be&quot;</td></tr><tr><td>riċeviment</td><td>reception</td><td>Masculine loanword</td></tr><tr><td>fil-lukanda</td><td>at the hotel</td><td>Contracted <code>f&#39;</code> + <code>il-lukanda</code></td></tr><tr><td>Marina</td><td>Marina</td><td>Hotel name</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġobkom, ikkonfermaw jekk tistgħux tattendu sal-1 ta&#39; Lulju.</p><p><strong>Translation:</strong> Please confirm by 1 July whether you will be able to attend.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jekk jogħġobkom</td><td>please</td><td>Polite expression addressed to several people</td></tr><tr><td>ikkonfermaw</td><td>confirm</td><td>Plural imperative</td></tr><tr><td>jekk</td><td>whether; if</td><td>Introduces an indirect question here</td></tr><tr><td>tistgħux</td><td>whether you can</td><td><code>tistgħu</code> &quot;you (plural) can&quot; + marker <code>-x</code></td></tr><tr><td>tattendu</td><td>you attend</td><td>Second-person plural form</td></tr><tr><td>sal-1</td><td>by the 1st; until the 1st</td><td>Contracted <code>sa</code> + <code>l-</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Date linker</td></tr><tr><td>Lulju</td><td>July</td><td>Month name</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nistennew bil-ħerqa li niċċelebraw dan il-jum speċjali magħkom.</p><p><strong>Translation:</strong> We look forward to celebrating this special day with you.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nistennew</td><td>we wait; we look forward</td><td>First-person plural form</td></tr><tr><td>bil-ħerqa</td><td>eagerly; with anticipation</td><td>Fixed adverbial phrase</td></tr><tr><td>li</td><td>to; introduces a clause</td><td>Conjunction</td></tr><tr><td>niċċelebraw</td><td>we celebrate</td><td>First-person plural form</td></tr><tr><td>dan</td><td>this</td><td>Masculine singular demonstrative, agreeing with <code>jum</code></td></tr><tr><td>il-jum</td><td>the day</td><td>Masculine noun with the definite article</td></tr><tr><td>speċjali</td><td>special</td><td>Adjective</td></tr><tr><td>magħkom</td><td>with you (plural)</td><td><code>ma&#39;</code> &quot;with&quot; + <code>-kom</code> &quot;you&quot;</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Anna u Mark</p><p><strong>Translation:</strong> Regards, Anna and Mark (email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Anna</td><td>Anna</td><td>Name</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>Mark</td><td>Mark</td><td>Name</td></tr></tbody></table>',49),o=[n];function i(l,s,h,m,c,u){return e(),a("div",null,o)}const p=t(r,[["render",i]]);export{b as __pageData,p as default};
